package com.landportal.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserDetailsService uds; public JwtFilter(JwtService j,UserDetailsService u){jwt=j;uds=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,java.io.IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String email=jwt.email(h.substring(7));var d=uds.loadUserByUsername(email);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}}c.doFilter(r,s);} }
